// Reformat measured RGB voxels in millimetres. No synthetic anatomy is added.
export function obliqueSlice(data,m,{yaw=0,pitch=0,offset=0,size=320,point=null,spanMm=null}={}){
 if(data.length!==m.width*m.height*m.depth*3)throw Error('Hacim boyutu uyuşmuyor');
 if(![yaw,pitch,offset,size].every(Number.isFinite)||size<2||size>1024)throw Error('Geçersiz kesit parametresi');
 size=Math.round(size);const [sx,sy,sz]=m.spacingMm,extent=[(m.width-1)*sx,(m.height-1)*sy,(m.depth-1)*sz],span=spanMm??Math.hypot(...extent),a=yaw*Math.PI/180,b=pitch*Math.PI/180;
 const u=[Math.cos(a),0,-Math.sin(a)],v=[Math.sin(a)*Math.sin(b),Math.cos(b),Math.cos(a)*Math.sin(b)],n=[Math.sin(a)*Math.cos(b),-Math.sin(b),Math.cos(a)*Math.cos(b)],p=point?[point.x*sx,point.y*sy,point.z*sz]:extent.map(x=>x/2),center=p.map((x,i)=>x+n[i]*offset),out=new Uint8ClampedArray(size*size*4);
 const at=(x,y,z,c)=>data[((z*m.height+y)*m.width+x)*3+c];let validPixels=0;
 for(let row=0;row<size;row++)for(let col=0;col<size;col++){
  const dx=(col/(size-1)-.5)*span,dy=(row/(size-1)-.5)*span,q=center.map((x,i)=>(x+u[i]*dx+v[i]*dy)/[sx,sy,sz][i]),k=(row*size+col)*4;
  if(q.some((x,i)=>x<0||x>[m.width-1,m.height-1,m.depth-1][i])){out.set([18,32,47,255],k);continue;}
  const [x,y,z]=q.map(Math.floor),[fx,fy,fz]=q.map((v,i)=>v-Math.floor(q[i])),x1=Math.min(x+1,m.width-1),y1=Math.min(y+1,m.height-1),z1=Math.min(z+1,m.depth-1);validPixels++;
  for(let c=0;c<3;c++){const a0=at(x,y,z,c)*(1-fx)+at(x1,y,z,c)*fx,a1=at(x,y1,z,c)*(1-fx)+at(x1,y1,z,c)*fx,b0=at(x,y,z1,c)*(1-fx)+at(x1,y,z1,c)*fx,b1=at(x,y1,z1,c)*(1-fx)+at(x1,y1,z1,c)*fx;out[k+c]=(a0*(1-fy)+a1*fy)*(1-fz)+(b0*(1-fy)+b1*fy)*fz;}out[k+3]=255;
 }
 return {width:size,height:size,data:out,validPixels,spanMm:span};
}
export function installObliqueViewer(viewer){
 const body=viewer.dialog.querySelector('#volumeBody'),mode=document.createElement('div');mode.className='volume-mode';mode.innerHTML='<button id="volumeAxes" aria-pressed="true">Üç düzlem</button><button id="volumeOblique" aria-pressed="false">Serbest eğik kesit</button>';body.prepend(mode);
 const panel=document.createElement('section');panel.className='photo-oblique';panel.hidden=true;panel.innerHTML='<div class="photo-oblique-image"><canvas id="photoObliqueCanvas" aria-label="Gerçek renkli hacimden eğik kesit"></canvas><span>Gerçek fotoğraf hacmi · Erkek göğüs</span></div><div class="photo-oblique-controls"><h3>Kesit düzlemini döndür</h3><label>Yatay açı <output id="photoYawValue">0°</output></label><input id="photoYaw" type="range" min="-180" max="180" value="0"><label>Dikey açı <output id="photoPitchValue">0°</output></label><input id="photoPitch" type="range" min="-90" max="90" value="0"><label>Noktadan uzaklık <output id="photoOffsetValue">0 mm</output></label><input id="photoOffset" type="range" min="-450" max="450" value="0" step="1"><button id="photoReset">Açıyı sıfırla</button><p id="photoSliceStatus" role="status"></p><p>Seçilen hacim noktasından geçen bir düzlem oluşturur. Renkler kaynak fotoğraflardan örneklenir; mevcut çözünürlüğün ötesinde ayrıntı eklenmez.</p></div>';mode.after(panel);
 const q=s=>panel.querySelector(s),extent=Math.hypot((viewer.meta.width-1)*viewer.meta.spacingMm[0],(viewer.meta.height-1)*viewer.meta.spacingMm[1],(viewer.meta.depth-1)*viewer.meta.spacingMm[2]);q('#photoOffset').min=-Math.ceil(extent);q('#photoOffset').max=Math.ceil(extent);
 let frame=0;viewer.disposeOblique=()=>{if(frame)cancelAnimationFrame(frame);frame=0;};const draw=()=>{frame=0;if(panel.hidden||!viewer.data)return;const yaw=Number(q('#photoYaw').value),pitch=Number(q('#photoPitch').value),offset=Number(q('#photoOffset').value),slice=obliqueSlice(viewer.data,viewer.meta,{yaw,pitch,offset,size:384,point:viewer.point});const canvas=q('canvas');canvas.width=slice.width;canvas.height=slice.height;canvas.getContext('2d').putImageData(new ImageData(slice.data,slice.width,slice.height),0,0);q('#photoYawValue').textContent=yaw+'°';q('#photoPitchValue').textContent=pitch+'°';q('#photoOffsetValue').textContent=offset+' mm';q('#photoSliceStatus').textContent=slice.validPixels?'Düzlem fotoğraf hacmini kesiyor.':'Bu konumda hacmin dışında kaldın; uzaklığı azalt.';};
 panel.querySelectorAll('input').forEach(el=>el.oninput=()=>{if(!frame)frame=requestAnimationFrame(draw);});q('#photoReset').onclick=()=>{q('#photoYaw').value=0;q('#photoPitch').value=0;q('#photoOffset').value=0;draw();};
 const setMode=on=>{if(!on)viewer.disposeOblique();panel.hidden=!on;body.querySelector('.volume-views').hidden=on;body.querySelector('.volume-plane-tabs').hidden=on;body.querySelector('#volumeExtent').hidden=on;body.querySelector('#volumeSpaceOpen').hidden=on;mode.querySelector('#volumeAxes').setAttribute('aria-pressed',String(!on));mode.querySelector('#volumeOblique').setAttribute('aria-pressed',String(on));if(on){viewer.space?.dispose();viewer.space=null;body.querySelector('#volumeSpace').hidden=true;body.querySelector('#volumeSpaceNote').hidden=true;body.querySelector('#volumeSpaceOpen').setAttribute('aria-pressed','false');body.querySelector('#volumeSpaceOpen').textContent='3B kesişim görünümünü aç';draw();}};
 mode.querySelector('#volumeAxes').onclick=()=>setMode(false);mode.querySelector('#volumeOblique').onclick=()=>setMode(true);
}
